create or replace function public.refresh_business_metric_leaderboards() returns void language plpgsql security definer set search_path=public as $$ begin delete from public.business_metric_leaderboards; insert into public.business_metric_leaderboards (id,business_id,metric,period_start,period_end,rank,value) select gen_random_uuid(),x.business_id,x.metric,current_date-29,current_date,row_number() over(partition by x.metric order by x.value desc,x.business_id),x.value from (select b.id business_id,'check_ins' metric,count(c.id)::numeric value from businesses b left join locations l on l.business_id=b.id left join check_ins c on c.location_id=l.id where coalesce(b.is_demo_test,false)=false group by b.id union all select b.id,'reviews',count(r.id)::numeric from businesses b left join locations l on l.business_id=b.id left join reviews r on r.location_id=l.id where coalesce(b.is_demo_test,false)=false group by b.id union all select b.id,'favorites',count(f.user_id)::numeric from businesses b left join locations l on l.business_id=b.id left join favorites f on f.location_id=l.id where coalesce(b.is_demo_test,false)=false group by b.id) x; end; $$; grant execute on function public.refresh_business_metric_leaderboards() to authenticated; select public.refresh_business_metric_leaderboards();
